package cl.gakuto.kizuna.launch

import java.io.File
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder

/** Generated byte fixtures only: these files are not playable games. */
class Ps1ArchivePreparationTest {
    @get:Rule val temp = TemporaryFolder()

    @Test fun singleChdIsoAndPbpAreExtractedWithoutChangingBytes() {
        listOf("CHD", "iso", "pbp").forEach { ext ->
            val data = ByteArray(8192) { (it % 251).toByte() }
            val zip = archive("single-$ext.zip", mapOf("folder/game.$ext" to data, "readme.txt" to byteArrayOf(1)))
            val result = prepare(zip)
            assertEquals("folder/game.$ext", result.entryName)
            assertArrayEquals(data, result.file.readBytes())
            RomPreparedPayloadValidator.validate(result.file)
        }
    }

    @Test fun twoDiscsInOneZipMustNotSilentlySelectOne() {
        rejectsWithoutWriting(mapOf("disc1.chd" to payload, "disc2.chd" to payload))
    }

    @Test fun twoRepresentationsMustNotSilentlyChooseARelease() {
        rejectsWithoutWriting(mapOf("game.chd" to payload, "game.iso" to payload))
    }

    @Test fun bareBinCannotLoseItsCueDuringPreparation() {
        rejectsWithoutWriting(mapOf("track.bin" to payload))
    }

    @Test fun cueBinAndPlaylistBundlesRemainExplicitlyUnsupported() {
        rejectsWithoutWriting(mapOf("game.cue" to "FILE track.bin BINARY".toByteArray(), "track.bin" to payload))
        rejectsWithoutWriting(mapOf("game.m3u" to "disc1.chd\ndisc2.chd\n".toByteArray(), "disc1.chd" to payload))
    }

    @Test fun traversalAndTruncatedPayloadsAreRejectedAndArchiveIsRetained() {
        rejectsWithoutWriting(mapOf("../game.chd" to payload))
        val zip = archive("short.zip", mapOf("game.chd" to ByteArray(20)))
        assertTrue(runCatching { prepare(zip) }.isFailure)
        assertTrue(zip.isFile)
    }

    private val payload get() = ByteArray(8192) { 7 }

    private fun rejectsWithoutWriting(entries: Map<String, ByteArray>) {
        val zip = archive("fixture-${temp.root.listFiles()!!.size}.zip", entries)
        val before = zip.readBytes()
        val out = temp.newFolder()
        val failure = runCatching {
            RomArchivePreparer.prepareZip("ps1", "PlayStation", zip) { File(out, it) }
        }.exceptionOrNull()
        assertTrue("Expected explicit rejection, got $failure", failure is IllegalArgumentException)
        assertTrue("No payload may be selected from an ambiguous bundle", out.listFiles()!!.isEmpty())
        assertArrayEquals(before, zip.readBytes())
    }

    private fun prepare(zip: File): RomArchivePreparer.PreparedZipEntry {
        val out = temp.newFolder()
        return RomArchivePreparer.prepareZip("ps1", "PlayStation", zip) { File(out, it) }
    }

    private fun archive(name: String, entries: Map<String, ByteArray>): File = temp.newFile(name).also { file ->
        ZipOutputStream(file.outputStream()).use { zip ->
            entries.forEach { (name, bytes) ->
                zip.putNextEntry(ZipEntry(name))
                zip.write(bytes)
                zip.closeEntry()
            }
        }
    }
}
